using Microsoft.EntityFrameworkCore.Diagnostics;
using Microsoft.AspNetCore.Http;
using System.Security.Claims;
using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using Demo.Api.Contracts;
using Demo.Api.Data;
using Demo.Api.Domain;
using Demo.Api.Services;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;
namespace Demo.Api.Tests;
public sealed class ManufacturingTests(ApiFixture fixture) : IClassFixture<ApiFixture>, IAsyncLifetime
{
    private HttpClient client = null!;
    private Guid actor;
    private static CancellationToken Ct => TestContext.Current.CancellationToken;
    private static readonly JsonSerializerOptions Json = new(JsonSerializerDefaults.Web) { Converters = {new JsonStringEnumConverter()} };
    public async ValueTask InitializeAsync() { (client,actor) = await Login(UserRole.Admin); }
    public ValueTask DisposeAsync() {client.Dispose();return ValueTask.CompletedTask;}
    private async Task<(HttpClient,Guid)> Login(UserRole role) {
        using var scope=fixture.App.Services.CreateScope();var auth=scope.ServiceProvider.GetRequiredService<AuthService>();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var email=$"mfg-{Guid.NewGuid():N}@example.com";var registered=(await auth.Register(new("Warehouse operator",email,"WarehouseTest123!"),Ct))!;
        (await db.Users.FindAsync([registered.Id],Ct))!.Role=role;await db.SaveChangesAsync(Ct);var token=(await auth.Login(new(email,"WarehouseTest123!"),Ct))!;
        var http=fixture.App.CreateClient();http.DefaultRequestHeaders.Authorization=new("Bearer",token.AccessToken);return(http,registered.Id);
    }
    private async Task<T> Body<T>(HttpResponseMessage r,HttpStatusCode status=HttpStatusCode.OK) {Assert.True(status==r.StatusCode, $"Expected {status}, actual {r.StatusCode}: " + await r.Content.ReadAsStringAsync(Ct) + string.Join("\n",fixture.App.Logs.Messages.Where(m=>m.Contains("Unexpected failure")).TakeLast(1)));return(await r.Content.ReadFromJsonAsync<T>(Json,Ct))!;}
    private async Task<Product> Product(ProductType type = ProductType.RawMaterial) { using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Category{Name="Manufacturing category"};var p=new Product{Name=$"MFG {Guid.NewGuid():N}",CategoryId=c.Id,Price=2,IsActive=true,ProductType=type};db.AddRange(c,p);await db.SaveChangesAsync(Ct);return p; }
    private async Task<Guid> Warehouse() => (await Body<WarehouseResponse>(await client.PostAsJsonAsync("/api/warehouses",new WarehouseRequest($"M-{Guid.NewGuid():N}","Manufacturing warehouse","",""),Ct),HttpStatusCode.Created)).Id;
    private async Task Stock(Guid w,Guid p,int qty) => await Body<WarehouseStock>(await client.PostAsJsonAsync($"/api/warehouses/{w}/inventory/{p}/stock-in",new {quantity=qty,reason="Manufacturing test supply"},Ct));
    private async Task<int> Balance(Guid w,Guid p) => (await client.GetFromJsonAsync<WarehouseStock>($"/api/warehouses/{w}/inventory/{p}",Ct))!.QuantityOnHand;
    private BomRequest Recipe(Guid product, params (Guid Id,int Qty)[] lines) => new(product,$"V-{Guid.NewGuid():N}","Test recipe",1,lines.Select(x=>new BomItemRequest(x.Id,x.Qty)).ToList());
    private async Task<BomResponse> Bom(BomRequest r, bool activate = true) {var b=await Body<BomResponse>(await client.PostAsJsonAsync("/api/boms",r,Ct),HttpStatusCode.Created);return activate?await Body<BomResponse>(await client.PostAsync($"/api/boms/{b.Id}/activate",null,Ct)):b;}
    private ProductionRequest Input(BomResponse b,Guid source,Guid destination,int qty=1) => new(b.ProductId,b.Id,qty,source,destination,null,null,"private manufacturing note");
    private async Task<ProductionResponse> Order(ProductionRequest r) => await Body<ProductionResponse>(await client.PostAsJsonAsync("/api/production-orders",r,Ct),HttpStatusCode.Created);
    private Task<HttpResponseMessage> Command(Guid id,string command) => client.PostAsync($"/api/production-orders/{id}/{command}",null,Ct);
    private async Task<ProductionResponse> Transition(Guid id,string command) => await Body<ProductionResponse>(await Command(id,command));
    private async Task<(Product F,Product M,Guid S,Guid D,BomResponse B,ProductionResponse O)> Setup(int stock=100,int per=4,int planned=10) {var f=await Product(ProductType.FinishedGood);var m=await Product();var s=await Warehouse();var d=await Warehouse();if(stock>0)await Stock(s,m.Id,stock);var b=await Bom(Recipe(f.Id,(m.Id,per)));var o=await Order(Input(b,s,d,planned));return(f,m,s,d,b,o);}
    [Fact] public async Task Valid_recipe_draft_edit_and_filters_work() {var f=await Product(ProductType.FinishedGood);var m=await Product();var n=await Product();var request=Recipe(f.Id,(m.Id,2));var b=await Bom(request,false);var edited=await Body<BomResponse>(await client.PutAsJsonAsync($"/api/boms/{b.Id}",request with {Items=[new(n.Id,3)],Name="Edited"},Ct));Assert.Equal(n.Id,Assert.Single(edited.Items).MaterialProductId);Assert.Null(edited.ActivatedAt);var page=await Body<ReportPage<BomResponse>>(await client.GetAsync($"/api/boms?productId={f.Id}&version={request.Version}&bomStatus=Draft&sort=version",Ct));Assert.Equal(b.Id,Assert.Single(page.Items).Id);}
    [Theory][InlineData("empty")][InlineData("duplicate")][InlineData("zero")][InlineData("negative")][InlineData("self")][InlineData("base")][InlineData("product")][InlineData("material")]
    public async Task Invalid_recipes_are_rejected(string kind) {var f=await Product(ProductType.FinishedGood);var m=await Product();var request=Recipe(f.Id,(m.Id,2));request=kind switch {"empty"=>request with{Items=[]},"duplicate"=>request with{Items=[new(m.Id,1),new(m.Id,2)]},"zero"=>request with{Items=[new(m.Id,0)]},"negative"=>request with{Items=[new(m.Id,-1)]},"self"=>request with{Items=[new(f.Id,1)]},"base"=>request with{BaseQuantity=0},"product"=>request with{ProductId=m.Id,Items=[new(f.Id,2)]},_=>request with{Items=[new((await Product(ProductType.FinishedGood)).Id,1)]}};Assert.Equal(kind is "product" or "material"?HttpStatusCode.Conflict:HttpStatusCode.BadRequest,(await client.PostAsJsonAsync("/api/boms",request,Ct)).StatusCode);}
    [Fact] public async Task Versions_unique_and_activation_atomic_immutable() {var f=await Product(ProductType.FinishedGood);var m=await Product();var r=Recipe(f.Id,(m.Id,2));var b=await Bom(r);Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsJsonAsync("/api/boms",r,Ct)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/boms/{b.Id}",r,Ct)).StatusCode);var b2=await Bom(Recipe(f.Id,(m.Id,3)),false);var b3=await Bom(Recipe(f.Id,(m.Id,5)),false);Assert.All(await Task.WhenAll(client.PostAsync($"/api/boms/{b2.Id}/activate",null,Ct),client.PostAsync($"/api/boms/{b3.Id}/activate",null,Ct)),x=>Assert.Equal(HttpStatusCode.OK,x.StatusCode));var active=await Body<ReportPage<BomResponse>>(await client.GetAsync($"/api/boms?productId={f.Id}&bomStatus=Active",Ct));Assert.Single(active.Items);Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/boms/{b.Id}",r,Ct)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await client.PostAsync($"/api/boms/{b.Id}/activate",null,Ct)).StatusCode);}
    [Fact] public async Task Snapshot_scaling_preview_and_bom_retirement_preserve_history() {var x=await Setup();var scaled=await Bom(Recipe(x.F.Id,(x.M.Id,6)) with{BaseQuantity=2});var o=await Order(Input(scaled,x.S,x.D,10));Assert.Equal(30,Assert.Single(o.Materials).QuantityRequired);var preview=await Body<List<MaterialAvailability>>(await client.PostAsJsonAsync("/api/production-orders/preview",Input(scaled,x.S,x.D,10),Ct));Assert.Equal(30,Assert.Single(preview).QuantityRequired);await Bom(Recipe(x.F.Id,(x.M.Id,9)));var prior=await Body<ProductionResponse>(await client.GetAsync($"/api/production-orders/{o.Id}",Ct));Assert.Equal(scaled.Id,prior.BillOfMaterialsId);Assert.Equal(30,Assert.Single(prior.Materials).QuantityRequired);await Transition(o.Id,"release");await Transition(o.Id,"start");Assert.Equal(70,await Balance(x.S,x.M.Id));}
    [Theory][InlineData(1,1,2,"fractionalMaterialRequirement")][InlineData(2147483647,2,1,"manufacturingOverflow")]
    public async Task Fractional_and_overflow_calculations_rejected(int required,int planned,int basis,string code) {var f=await Product(ProductType.FinishedGood);var m=await Product();var w=await Warehouse();var b=await Bom(Recipe(f.Id,(m.Id,required)) with{BaseQuantity=basis});var response=await client.PostAsJsonAsync("/api/production-orders",Input(b,w,w,planned),Ct);Assert.Equal(HttpStatusCode.BadRequest,response.StatusCode);Assert.Contains(code,await response.Content.ReadAsStringAsync(Ct));}
    [Fact] public async Task Creation_release_and_unique_numbers_do_not_change_stock() {var x=await Setup();var o2=await Order(Input(x.B,x.S,x.D));Assert.NotEqual(x.O.ProductionOrderNumber,o2.ProductionOrderNumber);Assert.Equal(0,x.O.ProducedQuantity);Assert.Equal(100,await Balance(x.S,x.M.Id));Assert.Equal(ProductionStatus.Released,(await Transition(x.O.Id,"release")).Status);Assert.Equal(100,await Balance(x.S,x.M.Id));Assert.Empty(await Body<List<MovementResponse>>(await client.GetAsync($"/api/production-orders/{x.O.Id}/movements",Ct)));}
    [Fact] public async Task Full_lifecycle_consumes_and_outputs_once_with_authenticated_audits() {var x=await Setup();await Transition(x.O.Id,"release");var started=await Transition(x.O.Id,"start");Assert.Equal(ProductionStatus.InProgress,started.Status);Assert.Equal(actor,started.StartedByUserId);Assert.Equal(40,Assert.Single(started.Materials).QuantityConsumed);await Transition(x.O.Id,"start");Assert.Equal(60,await Balance(x.S,x.M.Id));var completed=await Transition(x.O.Id,"complete");await Transition(x.O.Id,"complete");Assert.Equal(ProductionStatus.Completed,completed.Status);Assert.Equal(10,completed.ProducedQuantity);Assert.Equal(actor,completed.CompletedByUserId);Assert.NotNull(completed.StartedAt);Assert.NotNull(completed.CompletedAt);Assert.Equal(10,await Balance(x.D,x.F.Id));Assert.Equal(0,await Balance(x.S,x.F.Id));var movements=await Body<List<MovementResponse>>(await client.GetAsync($"/api/production-orders/{x.O.Id}/movements",Ct));Assert.Equal(2,movements.Count);Assert.All(movements,m=>{Assert.Equal(x.O.Id,m.ProductionOrderId);Assert.Equal(actor,m.CreatedByUserId);});Assert.Contains(movements,m=>m.MovementType==MovementType.ProductionConsumption&&m.WarehouseId==x.S&&m.Quantity==40);Assert.Contains(movements,m=>m.MovementType==MovementType.ProductionOutput&&m.WarehouseId==x.D&&m.Quantity==10);var audits=await Body<AuditPage>(await client.GetAsync("/api/audit-logs?entityName=ProductionOrder&pageSize=100",Ct));foreach(var action in new[]{"Create","ProductionRelease","ProductionStart","ProductionComplete"})Assert.Single(audits.Items,a=>a.EntityId==x.O.Id&&a.Action==action&&a.UserId==actor);Assert.DoesNotContain("private manufacturing note",JsonSerializer.Serialize(audits));}
    [Theory][InlineData("Draft","start")][InlineData("Draft","complete")][InlineData("Released","complete")][InlineData("InProgress","cancel")][InlineData("InProgress","release")][InlineData("Completed","cancel")][InlineData("Cancelled","release")]
    public async Task Invalid_transitions_do_not_change_stock(string state,string command) {var x=await Setup();if(state is "Released" or "InProgress" or "Completed")await Transition(x.O.Id,"release");if(state is "InProgress" or "Completed")await Transition(x.O.Id,"start");if(state=="Completed")await Transition(x.O.Id,"complete");if(state=="Cancelled")await Transition(x.O.Id,"cancel");Assert.Equal(HttpStatusCode.Conflict,(await Command(x.O.Id,command)).StatusCode);Assert.Equal(state is "InProgress" or "Completed"?60:100,await Balance(x.S,x.M.Id));}
    [Fact] public async Task Draft_edit_and_prestart_cancellation_work_final_orders_cannot_edit() {var x=await Setup();var edited=await Body<ProductionResponse>(await client.PutAsJsonAsync($"/api/production-orders/{x.O.Id}",Input(x.B,x.D,x.S,3),Ct));Assert.Equal(12,Assert.Single(edited.Materials).QuantityRequired);await Transition(x.O.Id,"release");await Transition(x.O.Id,"cancel");Assert.Equal(100,await Balance(x.S,x.M.Id));Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/production-orders/{x.O.Id}",Input(x.B,x.S,x.D),Ct)).StatusCode);var next=await Order(Input(x.B,x.S,x.D));await Transition(next.Id,"release");await Transition(next.Id,"start");await Transition(next.Id,"complete");Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/production-orders/{next.Id}",Input(x.B,x.S,x.D),Ct)).StatusCode);}
    [Fact] public async Task Shortage_is_warehouse_specific_and_multi_material_failure_is_atomic() {var x=await Setup(100,4,10);var second=await Product();await Stock(x.D,second.Id,100);await Stock(x.S,second.Id,3);var b=await Bom(Recipe(x.F.Id,(x.M.Id,4),(second.Id,1)));var o=await Order(Input(b,x.S,x.D,10));var availability=await Body<List<MaterialAvailability>>(await client.GetAsync($"/api/production-orders/{o.Id}/material-availability",Ct));Assert.Equal(7,availability.Single(m=>m.MaterialProductId==second.Id).ShortageQuantity);var report=await Body<ReportPage<MaterialRequirementRow>>(await client.GetAsync($"/api/reports/material-shortages?productionOrderId={o.Id}",Ct));Assert.Equal(7,Assert.Single(report.Items).ShortageQuantity);await Transition(o.Id,"release");Assert.Equal(HttpStatusCode.Conflict,(await Command(o.Id,"start")).StatusCode);Assert.Equal(100,await Balance(x.S,x.M.Id));Assert.Equal(3,await Balance(x.S,second.Id));Assert.Empty(await Body<List<MovementResponse>>(await client.GetAsync($"/api/production-orders/{o.Id}/movements",Ct)));Assert.Equal(ProductionStatus.Released,(await Body<ProductionResponse>(await client.GetAsync($"/api/production-orders/{o.Id}",Ct))).Status);}
    [Fact] public async Task Same_warehouse_is_allowed_and_unavailable_stock_is_zero() {var x=await Setup(0,1,2);var o=await Order(Input(x.B,x.S,x.S,2));Assert.Equal(2,Assert.Single(o.Materials).ShortageQuantity);await Stock(x.S,x.M.Id,2);await Transition(o.Id,"release");await Transition(o.Id,"start");await Transition(o.Id,"complete");Assert.Equal(0,await Balance(x.S,x.M.Id));Assert.Equal(2,await Balance(x.S,x.F.Id));}
    [Fact] public async Task Concurrent_orders_cannot_overconsume() {var x=await Setup(100,1,80);var o2=await Order(Input(x.B,x.S,x.D,70));await Transition(x.O.Id,"release");await Transition(o2.Id,"release");var responses=await Task.WhenAll(Command(x.O.Id,"start"),Command(o2.Id,"start"));Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Contains(await Balance(x.S,x.M.Id),new[]{20,30});}
    [Fact] public async Task Concurrent_same_order_across_api_instances_start_complete_once() {var x=await Setup();await Transition(x.O.Id,"release");using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();await using var app=new TestApplication(db.Database.GetConnectionString()!);using var other=app.CreateClient();other.DefaultRequestHeaders.Authorization=client.DefaultRequestHeaders.Authorization;foreach(var command in new[]{"start","complete"})Assert.All(await Task.WhenAll(Command(x.O.Id,command),other.PostAsync($"/api/production-orders/{x.O.Id}/{command}",null,Ct)),r=>Assert.Equal(HttpStatusCode.OK,r.StatusCode));Assert.Equal(60,await Balance(x.S,x.M.Id));Assert.Equal(10,await Balance(x.D,x.F.Id));Assert.Equal(2,(await Body<List<MovementResponse>>(await client.GetAsync($"/api/production-orders/{x.O.Id}/movements",Ct))).Count);}
    [Fact] public async Task Concurrent_sales_confirmation_and_production_share_locks() {var x=await Setup(100,1,80);using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var c=new Customer{Name="Manufacturing customer"};db.Customers.Add(c);await db.SaveChangesAsync(Ct);var sales=await Body<OrderResponse>(await client.PostAsJsonAsync("/api/orders",new OrderRequest(c.Id,[new(x.M.Id,70)],x.S),Ct),HttpStatusCode.Created);await Transition(x.O.Id,"release");var r=await Task.WhenAll(Command(x.O.Id,"start"),client.PutAsJsonAsync($"/api/orders/{sales.Id}/status",new{status="Confirmed"},Ct));Assert.Single(r,a=>a.StatusCode==HttpStatusCode.OK);Assert.Single(r,a=>a.StatusCode==HttpStatusCode.Conflict);Assert.Contains(await Balance(x.S,x.M.Id),new[]{20,30});}
    [Fact] public async Task Concurrent_transfer_and_production_share_locks() {var x=await Setup(100,1,80);var tr=await Body<TransferResponse>(await client.PostAsJsonAsync("/api/stock-transfers",new TransferRequest(x.S,x.D,[new(x.M.Id,70)],""),Ct),HttpStatusCode.Created);await Transition(x.O.Id,"release");var r=await Task.WhenAll(Command(x.O.Id,"start"),client.PostAsync($"/api/stock-transfers/{tr.Id}/complete",null,Ct));Assert.Single(r,a=>a.StatusCode==HttpStatusCode.OK);Assert.Single(r,a=>a.StatusCode==HttpStatusCode.Conflict);Assert.Contains(await Balance(x.S,x.M.Id),new[]{20,30});}
    [Fact] public async Task Concurrent_completion_and_receipt_preserve_output() {var x=await Setup();await Transition(x.O.Id,"release");await Transition(x.O.Id,"start");var supplier=await Body<SupplierResponse>(await client.PostAsJsonAsync("/api/suppliers",new SupplierRequest($"P-{Guid.NewGuid():N}","Manufacturing supplier","","","","",""),Ct),HttpStatusCode.Created);var po=await Body<PurchaseResponse>(await client.PostAsJsonAsync("/api/purchase-orders",new PurchaseRequest(supplier.Id,null,"",[new(x.F.Id,3,2)]),Ct),HttpStatusCode.Created);await client.PostAsync($"/api/purchase-orders/{po.Id}/submit",null,Ct);var msg=new HttpRequestMessage(HttpMethod.Post,$"/api/purchase-orders/{po.Id}/receipts"){Content=JsonContent.Create(new ReceiptRequest([new(po.Items[0].Id,3)],"",x.D))};msg.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());var r=await Task.WhenAll(Command(x.O.Id,"complete"),client.SendAsync(msg,Ct));Assert.Equal(HttpStatusCode.OK,r[0].StatusCode);Assert.Equal(HttpStatusCode.Created,r[1].StatusCode);Assert.Equal(13,await Balance(x.D,x.F.Id));}
    [Fact] public async Task Completion_overflow_rolls_back_status_output_and_audit() {var x=await Setup();await Transition(x.O.Id,"release");await Transition(x.O.Id,"start");await Stock(x.D,x.F.Id,int.MaxValue);Assert.Equal(HttpStatusCode.Conflict,(await Command(x.O.Id,"complete")).StatusCode);Assert.Equal(int.MaxValue,await Balance(x.D,x.F.Id));var o=await Body<ProductionResponse>(await client.GetAsync($"/api/production-orders/{x.O.Id}",Ct));Assert.Equal(ProductionStatus.InProgress,o.Status);Assert.Equal(0,o.ProducedQuantity);Assert.Single(await Body<List<MovementResponse>>(await client.GetAsync($"/api/production-orders/{x.O.Id}/movements",Ct)));}
    [Theory][InlineData("start")][InlineData("complete")]
    public async Task Audit_failure_rolls_back_all_business_changes(string command) {var x=await Setup();await Transition(x.O.Id,"release");if(command=="complete")await Transition(x.O.Id,"start");using var scope=fixture.App.Services.CreateScope();var original=scope.ServiceProvider.GetRequiredService<AppDbContext>();var accessor=new HttpContextAccessor{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity([new("sub",actor.ToString()),new("name","Operator")],"test"))}};await using var failing=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(original.Database.GetConnectionString()).AddInterceptors(new RejectAudit()).Options,accessor);await Assert.ThrowsAsync<DbUpdateException>(()=>new ManufacturingService(failing).Transition(x.O.Id,command,actor,Ct));Assert.Equal(command=="start"?100:60,await Balance(x.S,x.M.Id));Assert.Equal(0,await Balance(x.D,x.F.Id));Assert.Equal(command=="start"?ProductionStatus.Released:ProductionStatus.InProgress,(await original.ProductionOrders.AsNoTracking().SingleAsync(o=>o.Id==x.O.Id,Ct)).Status);}
    private sealed class RejectAudit:SaveChangesInterceptor {public override ValueTask<InterceptionResult<int>> SavingChangesAsync(DbContextEventData data,InterceptionResult<int> result,CancellationToken ct=default){foreach(var e in data.Context!.ChangeTracker.Entries<AuditLog>().Where(e=>e.State==EntityState.Added))e.Entity.UserId=Guid.NewGuid();return ValueTask.FromResult(result);}}
    [Fact] public async Task Database_guards_prevent_history_snapshot_and_classification_corruption() {var x=await Setup();await Transition(x.O.Id,"release");await Transition(x.O.Id,"start");using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ProductionOrderMaterials\" SET \"QuantityRequired\"=1 WHERE \"ProductionOrderId\"={x.O.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"BillOfMaterialsItems\" SET \"QuantityRequired\"=1 WHERE \"BillOfMaterialsId\"={x.B.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"Products\" SET \"ProductType\"='FinishedGood' WHERE \"Id\"={x.M.Id}",Ct))).SqlState);await Transition(x.O.Id,"complete");Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ProductionOrders\" SET \"Notes\"='Changed' WHERE \"Id\"={x.O.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"InventoryMovements\" WHERE \"ProductionOrderId\"={x.O.Id}",Ct))).SqlState);}
    [Fact] public async Task Inactive_warehouse_and_product_prevent_start() {var x=await Setup();await Transition(x.O.Id,"release");using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();(await db.Products.FindAsync([x.M.Id],Ct))!.IsActive=false;await db.SaveChangesAsync(Ct);Assert.Equal(HttpStatusCode.Conflict,(await Command(x.O.Id,"start")).StatusCode);Assert.Equal(100,await Balance(x.S,x.M.Id));(await db.Products.FindAsync([x.M.Id],Ct))!.IsActive=true;(await db.Warehouses.FindAsync([x.S],Ct))!.IsActive=false;await db.SaveChangesAsync(Ct);Assert.Equal(HttpStatusCode.Conflict,(await Command(x.O.Id,"start")).StatusCode);}
    [Theory][InlineData("/boms")][InlineData("/production-orders")][InlineData("/reports/manufacturing")][InlineData("/reports/material-requirements")][InlineData("/reports/material-shortages")]
    public async Task Anonymous_read_rejected(string path) {using var anonymous=fixture.App.CreateClient();Assert.Equal(HttpStatusCode.Unauthorized,(await anonymous.GetAsync("/api"+path,Ct)).StatusCode);}
    [Theory][InlineData("/boms")][InlineData("/production-orders")][InlineData("/production-orders/00000000-0000-0000-0000-000000000001/start")][InlineData("/boms/00000000-0000-0000-0000-000000000001/activate")]
    public async Task Viewer_mutations_forbidden(string path) {var (viewer,_)=await Login(UserRole.Viewer);using(viewer)Assert.Equal(HttpStatusCode.Forbidden,(await viewer.PostAsJsonAsync("/api"+path,new{},Ct)).StatusCode);}
    [Fact] public async Task Manager_can_plan_start_complete_but_cannot_activate_bom() {var x=await Setup();var (manager,managerId)=await Login(UserRole.Manager);client.Dispose();client=manager;Assert.Equal(HttpStatusCode.Forbidden,(await client.PostAsync($"/api/boms/{x.B.Id}/deactivate",null,Ct)).StatusCode);var o=await Order(Input(x.B,x.S,x.D));await Transition(o.Id,"release");Assert.Equal(managerId,(await Transition(o.Id,"start")).StartedByUserId);await Transition(o.Id,"complete");using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var u=(await db.Users.FindAsync([managerId],Ct))!;u.Role=UserRole.Viewer;u.SecurityVersion++;await db.SaveChangesAsync(Ct);Assert.Equal(HttpStatusCode.Unauthorized,(await Command(x.O.Id,"release")).StatusCode);}
    [Fact] public async Task Lists_reports_kpis_and_pagination_use_database_values() {var x=await Setup();var r=await Body<ReportPage<ProductionResponse>>(await client.GetAsync($"/api/production-orders?productId={x.F.Id}&sourceWarehouseId={x.S}&destinationWarehouseId={x.D}&status=Draft&pageSize=1&search={x.O.ProductionOrderNumber}",Ct));Assert.Equal(x.O.Id,Assert.Single(r.Items).Id);var requirements=await Body<ReportPage<MaterialRequirementRow>>(await client.GetAsync($"/api/reports/material-requirements?productionOrderId={x.O.Id}",Ct));Assert.Equal(40,Assert.Single(requirements.Items).QuantityRequired);await Transition(x.O.Id,"release");await Transition(x.O.Id,"start");await Transition(x.O.Id,"complete");var kpis=await Body<ManufacturingKpis>(await client.GetAsync("/api/reports/manufacturing",Ct));using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();Assert.Equal(await db.ProductionOrders.CountAsync(o=>o.Status==ProductionStatus.Completed,Ct),kpis.Completed);Assert.Equal(await db.ProductionOrders.SumAsync(o=>(long)o.ProducedQuantity,Ct),kpis.TotalCompletedQuantity);}
    [Theory][InlineData("/boms?page=0")][InlineData("/production-orders?pageSize=101")][InlineData("/production-orders?status=99")][InlineData("/boms?bomStatus=unknown")][InlineData("/production-orders?start=2026-01-01")]
    public async Task Invalid_filters_rejected(string path) => Assert.Equal(HttpStatusCode.BadRequest,(await client.GetAsync("/api"+path,Ct)).StatusCode);
    [Fact] public async Task Only_unused_draft_bom_can_be_deleted() {var f=await Product(ProductType.FinishedGood);var m=await Product();var b=await Bom(Recipe(f.Id,(m.Id,1)),false);Assert.Equal(HttpStatusCode.NoContent,(await client.DeleteAsync($"/api/boms/{b.Id}",Ct)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await client.GetAsync($"/api/boms/{b.Id}",Ct)).StatusCode);var active=await Bom(Recipe(f.Id,(m.Id,1)));Assert.Equal(HttpStatusCode.Conflict,(await client.DeleteAsync($"/api/boms/{active.Id}",Ct)).StatusCode);}
    [Fact] public async Task Bom_and_production_line_edits_generate_one_audit_each() {var x=await Setup();var r=Recipe(x.F.Id,(x.M.Id,3));var b=await Bom(r,false);await Body<BomResponse>(await client.PutAsJsonAsync($"/api/boms/{b.Id}",r with{Items=[new(x.M.Id,5)]},Ct));var o=await Body<ProductionResponse>(await client.PutAsJsonAsync($"/api/production-orders/{x.O.Id}",Input(x.B,x.S,x.D,4),Ct));Assert.Equal(16,Assert.Single(o.Materials).QuantityRequired);var bLogs=await Body<AuditPage>(await client.GetAsync("/api/audit-logs?entityName=BillOfMaterials&action=Update&pageSize=100",Ct));Assert.Single(bLogs.Items,a=>a.EntityId==b.Id);var oLogs=await Body<AuditPage>(await client.GetAsync("/api/audit-logs?entityName=ProductionOrder&action=Update&pageSize=100",Ct));Assert.Single(oLogs.Items,a=>a.EntityId==x.O.Id);}
    [Fact] public async Task Concurrent_multi_material_starts_are_atomic() {var x=await Setup(100,1,80);var n=await Product();await Stock(x.S,n.Id,100);var b=await Bom(Recipe(x.F.Id,(x.M.Id,1),(n.Id,1)));var a=await Order(Input(b,x.S,x.D,80));var c=await Order(Input(b,x.S,x.D,70));await Transition(a.Id,"release");await Transition(c.Id,"release");var responses=await Task.WhenAll(Command(a.Id,"start"),Command(c.Id,"start"));Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.OK);Assert.Single(responses,r=>r.StatusCode==HttpStatusCode.Conflict);Assert.Equal(await Balance(x.S,x.M.Id),await Balance(x.S,n.Id));}
    [Fact] public async Task Product_classification_changes_are_guarded_at_api() {var x=await Setup();var r=new ProductRequest(x.M.Name,"",2,true,x.M.CategoryId,ProductType.FinishedGood);Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/products/{x.M.Id}",r,Ct)).StatusCode);}
    [Theory][InlineData("quantity")][InlineData("dates")][InlineData("bom")][InlineData("warehouse")]
    public async Task Invalid_production_inputs_rejected(string kind) {var x=await Setup();var input=Input(x.B,x.S,x.D);input=kind switch {"quantity"=>input with{PlannedQuantity=0},"dates"=>input with{PlannedStartDate=DateTimeOffset.UtcNow,PlannedEndDate=DateTimeOffset.UtcNow.AddDays(-1)},"bom"=>input with{BillOfMaterialsId=Guid.NewGuid()},_=>input with{SourceWarehouseId=Guid.NewGuid()}};Assert.Equal(kind is "bom" or "warehouse"?HttpStatusCode.Conflict:HttpStatusCode.BadRequest,(await client.PostAsJsonAsync("/api/production-orders",input,Ct)).StatusCode);}

    [Fact] public async Task Database_quantity_constraints_and_state_guards_cannot_bypass_consumption() {var x=await Setup();using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var draft=await Bom(Recipe(x.F.Id,(x.M.Id,1)),false);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"BillOfMaterials\" SET \"BaseQuantity\"=0 WHERE \"Id\"={draft.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ProductionOrderMaterials\" SET \"QuantityRequired\"=0 WHERE \"ProductionOrderId\"={x.O.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ProductionOrders\" SET \"ProducedQuantity\"=100 WHERE \"Id\"={x.O.Id}",Ct))).SqlState);Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"ProductionOrderMaterials\" WHERE \"ProductionOrderId\"={x.O.Id}",Ct))).SqlState);Assert.Equal("23505",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"BillOfMaterials\" SET \"IsActive\"=true, \"ActivatedAt\"=CURRENT_TIMESTAMP WHERE \"Id\"={draft.Id}",Ct))).SqlState);await Transition(x.O.Id,"release");Assert.Equal("23514",(await Assert.ThrowsAsync<PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"ProductionOrders\" SET \"Status\"='InProgress', \"StartedAt\"=CURRENT_TIMESTAMP, \"StartedByUserId\"={actor} WHERE \"Id\"={x.O.Id}",Ct))).SqlState);Assert.Equal(100,await Balance(x.S,x.M.Id));}
    [Fact] public async Task Open_production_prevents_destination_deactivation_and_inactive_destination_blocks_output() {var x=await Setup();Assert.Equal(HttpStatusCode.Conflict,(await client.PutAsJsonAsync($"/api/warehouses/{x.D}/status",new{isActive=false},Ct)).StatusCode);await Transition(x.O.Id,"release");await Transition(x.O.Id,"start");using var scope=fixture.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();(await db.Warehouses.FindAsync([x.D],Ct))!.IsActive=false;await db.SaveChangesAsync(Ct);Assert.Equal(HttpStatusCode.Conflict,(await Command(x.O.Id,"complete")).StatusCode);Assert.Equal(0,await Balance(x.D,x.F.Id));Assert.Equal(ProductionStatus.InProgress,(await Body<ProductionResponse>(await client.GetAsync($"/api/production-orders/{x.O.Id}",Ct))).Status);}
    [Fact] public async Task Manager_can_create_edit_recipe_draft_but_cannot_delete_activate() {var f=await Product(ProductType.FinishedGood);var m=await Product();var r=Recipe(f.Id,(m.Id,2));var(manager,_)=await Login(UserRole.Manager);client.Dispose();client=manager;var b=await Bom(r,false);await Body<BomResponse>(await client.PutAsJsonAsync($"/api/boms/{b.Id}",r with{BaseQuantity=2},Ct));Assert.Equal(HttpStatusCode.Forbidden,(await client.PostAsync($"/api/boms/{b.Id}/activate",null,Ct)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await client.DeleteAsync($"/api/boms/{b.Id}",Ct)).StatusCode);}

